  return (
    <div className='App'>
      <footer className='footer '>


<div className='_container'>
          <div className='footer__row'>
            <div className='footer__nav'>
              <div className='footer__nav-nav'>
                <a>home</a>
                <a>portfolio</a>
                <a>contacts</a>
              </div>
            </div>
            <div className='footer__title'>Vitalii Antonenko</div>
            <div className='footer__img'>
              <img src={fotoFooter} alt='' />
            </div>
            <div className='footer text'>moments of your life</div>
          </div>

        </div>


      </footer>
      <section className='section'>
        <div className="section__row _container">
<div className="section__l">
  <div className="section__l-1">
    <img src={sec1} alt="sec1" />
  </div>
  <div className="section__l-2">
  <img src={sec2} alt="sec2" />
  </div>
</div>
<div className="section__r">
  <div className="section__r-top">
  <img src={sec3} alt="sec3" />
  </div>
  <div className="section__r-bottom">
  <img src={sec4} alt="sec4" />
  </div>
  <div className="section__r-text"><a>I take happy, elegant and candid wedding photos that capture your day beautifully so you can remember it exactly how it happened...</a></div>

</div>
        </div>
      </section>

    <div className={classes.root}>
      <ImageList rowHeight={180} className={classes.imageList}>
        <ImageListItem key="Subheader" cols={2} style={{ height: 'auto' }}>
          <ListSubheader component="div">December</ListSubheader>
        </ImageListItem>
        {itemData.map((item) => (
          <ImageListItem key={item.img}>
            <img src={item.img} alt={item.title} />
            <ImageListItemBar
              title={item.title}
              subtitle={<span>by: {item.author}</span>}
              actionIcon={
                <IconButton aria-label={`info about ${item.title}`} className={classes.icon}>
                  <InfoIcon />
                </IconButton>
              }
            />
          </ImageListItem>
        ))}
      </ImageList>
    </div>  
    </div>
  );
}

export default App;
